unitScript:
test("attendance below 90% flags the student and exactly 90% does not", () => {
  const low = code.riskFlag({ present: 17, schoolDays: 20, failingGrades: 0, clearDays: 0 });
  assert.equal(low.flagged, true);
  assert.deepEqual(low.reasons, ["attendance"]);
  const exact = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 0, clearDays: 20 });
  assert.equal(exact.flagged, false);
  assert.deepEqual(exact.reasons, []);
});
test("two failing grades this term flag the student and one does not", () => {
  const two = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 2, clearDays: 0 });
  assert.equal(two.flagged, true);
  assert.deepEqual(two.reasons, ["grades"]);
  const one = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 1, clearDays: 20 });
  assert.equal(one.flagged, false);
});
test("only the student own counsellor and the head of year can see the flag", () => {
  const student = { counsellorId: "c1" };
  assert.equal(code.canSeeFlag({ role: "counsellor", id: "c1" }, student), true);
  assert.equal(code.canSeeFlag({ role: "head-of-year", id: "h1" }, student), true);
  assert.equal(code.canSeeFlag({ role: "counsellor", id: "c2" }, student), false);
  assert.equal(code.canSeeFlag({ role: "teacher", id: "t1" }, student), false);
  assert.equal(code.canSeeFlag({ role: "student", id: "s1" }, student), false);
  assert.equal(code.canSeeFlag({ role: "parent", id: "p1" }, student), false);
});
test("flag stays after 9 clear school days and clears on day 10", () => {
  const day9 = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 1, clearDays: 9 });
  assert.equal(day9.flagged, true);
  const day10 = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 1, clearDays: 10 });
  assert.equal(day10.flagged, false);
});
test("flag remains on day 10 if a condition still holds", () => {
  const att = code.riskFlag({ present: 17, schoolDays: 20, failingGrades: 0, clearDays: 10 });
  assert.equal(att.flagged, true);
  assert.deepEqual(att.reasons, ["attendance"]);
  const both = code.riskFlag({ present: 17, schoolDays: 20, failingGrades: 3, clearDays: 10 });
  assert.equal(both.flagged, true);
  assert.deepEqual(both.reasons, ["attendance", "grades"]);
});
test("invalid student input is rejected", () => {
  assert.throws(() => code.riskFlag({ present: 21, schoolDays: 20, failingGrades: 0, clearDays: 0 }), /present cannot exceed schoolDays/);
  assert.throws(() => code.riskFlag({ present: 20, schoolDays: 25, failingGrades: 0, clearDays: 0 }), /at most the last 20 school days/);
  assert.throws(() => code.riskFlag({ present: -1, schoolDays: 20, failingGrades: 0, clearDays: 0 }), /non-negative integers/);
  assert.throws(() => code.riskFlag(null), /student object required/);
});

