test("flags when attendance over the last 20 school days is below 90 percent even with no failing grades", function() {
  var result = code.riskFlag({ present: 17, schoolDays: 20, failingGrades: 0, clearDays: 0 });
  assert.equal(result.flagged, true);
  assert.deepEqual(result.reasons, ["attendance"]);
});
test("does not flag when attendance is exactly 90 percent and there are no failing grades", function() {
  var result = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 0, clearDays: 10 });
  assert.equal(result.flagged, false);
  assert.deepEqual(result.reasons, []);
});
test("flags when the current term has two or more failing grades even at 90 percent attendance", function() {
  var two = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 2, clearDays: 0 });
  var more = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 3, clearDays: 0 });
  assert.equal(two.flagged, true);
  assert.deepEqual(two.reasons, ["grades"]);
  assert.equal(more.flagged, true);
  assert.deepEqual(more.reasons, ["grades"]);
});
test("does not flag one current-term failing grade at 90 percent attendance and previous-term failing grades do not count", function() {
  var result = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 1, clearDays: 10 });
  assert.equal(result.flagged, false);
  assert.deepEqual(result.reasons, []);
});
test("only the student counsellor and the head of year can see the flag", function() {
  assert.equal(code.canSeeFlag("counsellor"), true);
  assert.equal(code.canSeeFlag("head-of-year"), true);
  assert.equal(code.canSeeFlag("teacher"), false);
  assert.equal(code.canSeeFlag("student"), false);
  assert.equal(code.canSeeFlag("parent"), false);
});
test("keeps the flag until neither condition has held for 10 consecutive school days", function() {
  var day9 = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 0, clearDays: 9 });
  var day10 = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 0, clearDays: 10 });
  assert.equal(day9.flagged, true);
  assert.deepEqual(day9.reasons, []);
  assert.equal(day10.flagged, false);
  assert.deepEqual(day10.reasons, []);
});
test("restarts the clear count if a condition returns and keeps the flag if either condition still holds on day 10", function() {
  var relapsedOnDay5 = code.riskFlag({ present: 17, schoolDays: 20, failingGrades: 0, clearDays: 5 });
  var attendanceOnDay10 = code.riskFlag({ present: 17, schoolDays: 20, failingGrades: 0, clearDays: 10 });
  var gradesOnDay10 = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 2, clearDays: 10 });
  var countRestarted = code.riskFlag({ present: 18, schoolDays: 20, failingGrades: 0, clearDays: 1 });
  assert.equal(relapsedOnDay5.flagged, true);
  assert.deepEqual(relapsedOnDay5.reasons, ["attendance"]);
  assert.equal(attendanceOnDay10.flagged, true);
  assert.deepEqual(attendanceOnDay10.reasons, ["attendance"]);
  assert.equal(gradesOnDay10.flagged, true);
  assert.deepEqual(gradesOnDay10.reasons, ["grades"]);
  assert.equal(countRestarted.flagged, true);
  assert.deepEqual(countRestarted.reasons, []);
});
test("shows a newly raised flag to the student counsellor", function() {
  var raised = code.riskFlag({ present: 17, schoolDays: 20, failingGrades: 0, clearDays: 0 });
  assert.equal(raised.flagged, true);
  assert.deepEqual(raised.reasons, ["attendance"]);
  assert.equal(code.canSeeFlag("counsellor"), true);
});

